void dei_sc_tx_flush( void )
{
    Q_Msg *q_msg ; 
    
    CRITICAL_TSK ; 

    C_ENTER_TSK ; 
    {                        
        do
        {
            q_msg = q_remove_c( dei_sc_tx_q_pending ) ;

            if( q_msg ) 
            {
                q_return( q_msg ) ; 
            }
        }
        while( q_msg ) ; 
    }
    C_LEAVE_TSK ; 
}

